// Shared rendering + review-queue logic for the review-gated pipeline.
//
// The daily workflow (scripts/update.mjs) only fetches the raw snapshot and
// refreshes the review queue under data/review/. The human-facing pages
// (CATALOG.md, TOP200.md) are regenerated by scripts/merge.mjs after the
// maintainer has reviewed the queue and recorded decisions in
// data/approved.json and data/curated.json.
//
// Convention (see data/review/README.md):
//   data/repositories.json  raw topic snapshot, scripts-only
//   data/approved.json      full_name -> approval date; the gate for what users see
//   data/curated.json       editorial decisions (exclusions, board exclusions, categories)
//   data/review/pending.*   new repositories awaiting the maintainer's review

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { assignableCategories, categoryFallback, categoryRules } from './categories.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export async function loadState() {
  const [snapshot, curated, approved] = await Promise.all([
    readFile(resolve(root, 'data/repositories.json'), 'utf8').then(JSON.parse),
    readFile(resolve(root, 'data/curated.json'), 'utf8').then(JSON.parse),
    readFile(resolve(root, 'data/approved.json'), 'utf8').then(JSON.parse),
  ]);
  const excluded = new Map(
    Object.entries(curated.excluded_repos || {}).map(([fullName, reason]) => [fullName.toLowerCase(), reason]),
  );
  const leaderboardExclusions = new Map(
    Object.entries(curated.leaderboard_exclusions || {}).map(([fullName, reason]) => [fullName.toLowerCase(), reason]),
  );
  const approvedNames = new Set(Object.keys(approved).map((fullName) => fullName.toLowerCase()));
  const date = snapshot.fetched_at.slice(0, 10);
  return { snapshot, curated, approved, approvedNames, excluded, leaderboardExclusions, date };
}

// Repositories shown in the catalog: description set, maintainer-approved,
// not excluded. The board is this set minus leaderboard_exclusions.
export function catalogRepositories(state) {
  return state.snapshot.repositories
    .filter((repo) => repo.description && repo.description.trim())
    .filter((repo) => !state.excluded.has(repo.full_name.toLowerCase()))
    .filter((repo) => state.approvedNames.has(repo.full_name.toLowerCase()));
}

export function boardRepositories(state) {
  return catalogRepositories(state).filter((repo) => !state.leaderboardExclusions.has(repo.full_name.toLowerCase()));
}

// New repositories that would enter the catalog but have not been approved
// yet. They stay queued here (keeping their original first_seen date) until
// the maintainer reviews them and runs scripts/merge.mjs.
export function computePending(state) {
  const pending = state.snapshot.repositories
    .filter((repo) => repo.description && repo.description.trim())
    .filter((repo) => !state.excluded.has(repo.full_name.toLowerCase()))
    .filter((repo) => !state.approvedNames.has(repo.full_name.toLowerCase()))
    .map((repo) => ({
      full_name: repo.full_name,
      html_url: repo.html_url,
      description: repo.description,
      language: repo.language,
      stargazers_count: repo.stargazers_count,
      forks_count: repo.forks_count,
      license: repo.license,
      created_at: repo.created_at,
      pushed_at: repo.pushed_at,
      topics: repo.topics || [],
    }))
    .sort((a, b) => b.stargazers_count - a.stargazers_count || a.full_name.localeCompare(b.full_name));
  const snapshotNames = new Set(state.snapshot.repositories.map((repo) => repo.full_name.toLowerCase()));
  // Approved repositories that vanished from the snapshot (deleted or renamed)
  // — surfaced so the maintainer can drop them from approved.json.
  const missing = Object.keys(state.approved)
    .filter((fullName) => !snapshotNames.has(fullName.toLowerCase()))
    .sort((a, b) => a.localeCompare(b));
  return { pending, missing };
}

const esc = (value) => String(value ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ');
const updated = (repo) => repo.updated_at.slice(0, 10);

export async function writePending(state) {
  const { pending, missing } = computePending(state);
  const pendingPath = resolve(root, 'data/review/pending.json');
  let previousFirstSeen = new Map();
  try {
    const previous = JSON.parse(await readFile(pendingPath, 'utf8'));
    for (const entry of previous.pending || []) {
      previousFirstSeen.set(entry.full_name.toLowerCase(), entry.first_seen);
    }
  } catch {
    // First run — no queue yet.
  }
  const today = new Date().toISOString().slice(0, 10);
  const entries = pending.map((entry) => ({
    first_seen: previousFirstSeen.get(entry.full_name.toLowerCase()) ?? today,
    ...entry,
  }));
  const queue = {
    generated_at: new Date().toISOString(),
    snapshot_date: state.date,
    pending: entries,
    missing,
  };
  await mkdir(resolve(root, 'data/review'), { recursive: true });
  await writeFile(pendingPath, `${JSON.stringify(queue, null, 2)}\n`);
  await writeFile(resolve(root, 'data/review/pending.md'), renderPendingMarkdown(queue));
}

function renderPendingMarkdown(queue) {
  const rows = queue.pending
    .map(
      (entry, index) =>
        `| ${index + 1} | [${entry.full_name}](${entry.html_url}) | ${entry.stargazers_count} | ${entry.created_at.slice(0, 10)} | ${entry.first_seen} | ${esc(entry.description || '—')} |`,
    )
    .join('\n');
  const missingLines = queue.missing.length ? queue.missing.map((name) => `- ${name}`).join('\n') : '- （无 / none）';
  return `# 待审核仓库 / Pending review

> 新增到 \`dsh-plugin\` Topic 下、带有简介、尚未经维护者核实的仓库。本文件由 \`scripts/update.mjs\` 每日刷新，仅供审核使用，不是用户可见页面。
>
> Repositories newly added to the \`dsh-plugin\` topic that the maintainer has not verified yet. Refreshed daily by \`scripts/update.mjs\`; review-only, not a user-facing page.

- 生成时间 / Generated: **${queue.generated_at.slice(0, 10)}**
- 快照日期 / Snapshot date: **${queue.snapshot_date} (UTC)**
- 待审核 / Pending: **${queue.pending.length}**
- 从快照消失的已核准仓库 / Approved repositories missing from the snapshot: **${queue.missing.length}**

审核决定记到数据文件后运行 \`node scripts/merge.mjs\` 生效：

- 通过 → 加入 [data/approved.json](../approved.json)（\`"owner/name": "YYYY-MM-DD"\`）
- 剔除 → 加入 [data/curated.json](../curated.json) 的 \`excluded_repos\` 并注明理由
- 只进目录、不进榜单 → 加入 \`approved.json\` + \`curated.json\` 的 \`leaderboard_exclusions\`

完整约定见 [data/review/README.md](./README.md)。

Record decisions in the data files, then run \`node scripts/merge.mjs\`:

- Approve → add to [data/approved.json](../approved.json) (\`"owner/name": "YYYY-MM-DD"\`)
- Exclude → add to \`excluded_repos\` in [data/curated.json](../curated.json) with a reason
- Catalog-only (not in the board) → add to \`approved.json\` + \`leaderboard_exclusions\` in \`curated.json\`

See [data/review/README.md](./README.md) for the full convention.

| # | Project | Stars | Created | First seen | Description |
| ---: | --- | ---: | --- | --- | --- |
${rows}

## 从快照消失的已核准仓库 / Approved repositories missing from the snapshot

已核准但已不在当前快照中（删除或改名），核实后从 [data/approved.json](../approved.json) 移除或更新名称。

Approved but no longer present in the current snapshot (deleted or renamed) — after checking, remove them from [data/approved.json](../approved.json) or update the name.

${missingLines}
`;
}

function categoryFor(state, repo, unknownOverrides) {
  const overrides = state.curated.category_overrides || {};
  const override = Object.entries(overrides).find(([key]) => key.toLowerCase() === repo.full_name.toLowerCase())?.[1];
  if (override) {
    const match = assignableCategories.find(([key]) => key === override);
    if (match) return match;
    unknownOverrides.add(`${repo.full_name} -> ${override}`);
  }
  const haystack = [repo.name || repo.full_name.split('/')[1], repo.description, ...(repo.topics || [])]
    .filter(Boolean)
    .join(' ');
  return categoryRules.find((rule) => rule[3].test(haystack)) || categoryFallback;
}

export function buildCatalog(state) {
  const unknownOverrides = new Set();
  const repositories = catalogRepositories(state)
    .map((repo) => {
      const category = categoryFor(state, repo, unknownOverrides);
      return {
        ...repo,
        category: category[0],
        category_zh: category[1],
        category_en: category[2],
      };
    })
    .sort((a, b) => b.stargazers_count - a.stargazers_count || a.full_name.localeCompare(b.full_name));
  const excludedCount = state.snapshot.repositories.filter(
    (repo) => repo.description && repo.description.trim() && state.excluded.has(repo.full_name.toLowerCase()),
  ).length;
  const totals = {
    languages: new Set(repositories.map((repo) => repo.language).filter(Boolean)).size,
    licenses: repositories.filter((repo) => repo.license).length,
    active: repositories.filter((repo) => !repo.archived && !repo.disabled).length,
  };
  const today = new Date().toISOString().slice(0, 10);

  const sections = categoryRules
    .map(([key, zh, en]) => [key, zh, en])
    .concat([categoryFallback])
    .map(([key, zh, en]) => {
      const group = repositories.filter((repo) => repo.category === key);
      if (!group.length) return '';
      const rows = group.map((repo) => `| [${repo.full_name}](${repo.html_url}) | ${esc(repo.description || '—')} | ${repo.language || '—'} | ${repo.stargazers_count} | ${repo.license || '—'} | ${updated(repo)} |`);
      return `## ${zh} / ${en} (${group.length})\n\n| Project | Description | Language | Stars | License | Updated |\n| --- | --- | --- | ---: | --- | --- |\n${rows.join('\n')}`;
    })
    .filter(Boolean)
    .join('\n\n');

  const catalog = `# DSH 插件全量目录 / Complete DSH Plugin Catalog\n\n[返回中文首页](./README.md) · [Back to English home](./README_EN.md) · [Star Top 200](./TOP200.md) · [作者自荐 / Author showcase](./SHOWCASE.md) · [JSON data](./data/repositories.json)\n\n本页自动收录 GitHub [\`dsh-plugin\` Topic](https://github.com/topics/dsh-plugin) 下已提供项目简介、并经维护者核实（[data/approved.json](./data/approved.json)）的公开仓库。${excludedCount} 个蹭 Topic 的非插件仓库（平台本体、其他 Agent 工具、同名目录站等）以及经编辑部拉黑的仓库已剔除，清单与理由见 [data/curated.json](./data/curated.json)。新增仓库先进入[待审核队列](./data/review/pending.md)，经人工核实后才会收录。本页是索引，不代表人工推荐、兼容性验证或安全背书。\n\nThis page automatically lists public repositories under GitHub's [\`dsh-plugin\` topic](https://github.com/topics/dsh-plugin) that have a description set and have been verified by the maintainer ([data/approved.json](./data/approved.json)). ${excludedCount} repositories that ride the topic without being DSH plugins (the platform itself, other agent tools, competing catalogs), plus editorially blacklisted repositories, are excluded — see [data/curated.json](./data/curated.json) for the full list and reasons. New repositories enter the [review queue](./data/review/pending.md) first and appear here only after human verification. It is an index, not a claim of editorial recommendation, compatibility, or security review.\n\n- Repositories: **${repositories.length}**\n- Primary languages: **${totals.languages}**\n- Declared licenses: **${totals.licenses}**\n- Refreshed: **${state.date} UTC**\n- 最近人工复核 / Last review merge: **${today}**\n\n${sections}\n\n## Data source\n\nGenerated by \`node scripts/merge.mjs\`. Complete metadata is available in [data/repositories.json](./data/repositories.json).\n`;

  return { catalog, stats: { repositories: repositories.length, ...totals }, warnings: unknownOverrides };
}

export function buildBoard(state, topN) {
  const repositories = boardRepositories(state).sort(
    (a, b) => b.stargazers_count - a.stargazers_count || a.full_name.localeCompare(b.full_name),
  );
  const top = repositories.slice(0, topN);
  // Only excluded repositories that would otherwise be listed (description set)
  // count here — mirrors the "excluded N" headline in CATALOG.md.
  const excludedCount = state.snapshot.repositories.filter(
    (repo) => repo.description && repo.description.trim() && state.excluded.has(repo.full_name.toLowerCase()),
  ).length;
  const boardExcludedCount = state.snapshot.repositories.filter(
    (repo) =>
      repo.description &&
      repo.description.trim() &&
      !state.excluded.has(repo.full_name.toLowerCase()) &&
      state.leaderboardExclusions.has(repo.full_name.toLowerCase()),
  ).length;
  const pendingCount = state.snapshot.repositories.filter(
    (repo) =>
      repo.description &&
      repo.description.trim() &&
      !state.excluded.has(repo.full_name.toLowerCase()) &&
      !state.approvedNames.has(repo.full_name.toLowerCase()),
  ).length;
  const today = new Date().toISOString().slice(0, 10);

  const rows = top.map(
    (repo, index) =>
      `| ${index + 1} | [${repo.full_name}](${repo.html_url}) | ${esc(repo.description || '—')} | ${repo.language || '—'} | ${repo.stargazers_count} | ${repo.license || '—'} | ${updated(repo)} |`,
  );

  return `# DSH 插件 Star 排行榜 Top ${topN} / Top ${topN} DSH Plugins by Stars\n\n[返回中文首页](./README.md) · [Back to English home](./README_EN.md) · [完整目录 / Full catalog](./CATALOG.md) · [作者自荐 / Author showcase](./SHOWCASE.md) · [JSON data](./data/repositories.json)\n\n按 Star 数排序的前 ${topN} 个 DSH 插件仓库，由 \`scripts/top.mjs\` 从 [data/repositories.json](./data/repositories.json) 快照生成，并随人工审核合并（\`scripts/merge.mjs\`）更新。新仓库先进入[待审核队列](./data/review/pending.md)，经维护者核实（[data/approved.json](./data/approved.json)）后才参与榜单。带有 \`dsh-plugin\` Topic 但并非 DSH 插件的仓库（平台本体、其他 Agent 工具、同名目录站等）以及编辑部拉黑的仓库已剔除；少数星数主要来自通用产品、并非 DSH 生态真实热度的仓库不参与榜单排序（仍保留在全量目录中），两处清单与理由分别记录在 [data/curated.json](./data/curated.json) 的 \`excluded_repos\` 与 \`leaderboard_exclusions\`。排名反映受欢迎程度，不代表安全性、兼容性或质量背书。\n\nThe top ${topN} DSH plugin repositories ranked by GitHub stars, generated by \`scripts/top.mjs\` from the [data/repositories.json](./data/repositories.json) snapshot and updated together with each human review merge (\`scripts/merge.mjs\`). New repositories enter the [review queue](./data/review/pending.md) first and rank here only after the maintainer has verified them ([data/approved.json](./data/approved.json)). Repositories that carry the \`dsh-plugin\` topic without being DSH plugins (the platform itself, other agent tools, competing catalogs) and editorially blacklisted repositories are excluded; a few repositories whose stars come mainly from a generic product rather than real DSH-ecosystem popularity are kept in the catalog but left out of this ranking. Both lists and their reasons live in [data/curated.json](./data/curated.json) under \`excluded_repos\` and \`leaderboard_exclusions\`. Ranking reflects popularity only — it is not a claim of security, compatibility, or quality.\n\n- 快照日期 / Snapshot date: **${state.date} (UTC)**\n- 收录条目 / Entries: **${top.length}**\n- 已剔除仓库 / Excluded repositories: **${excludedCount}**\n- 不参与榜单 / Kept out of the board: **${boardExcludedCount}**\n- 待审核 / Pending review: **${pendingCount}**（[data/review/pending.md](./data/review/pending.md)）\n- 最近人工复核 / Last review merge: **${today}**\n\n| # | Project | Description | Language | Stars | License | Updated |\n| ---: | --- | --- | --- | ---: | --- | --- |\n${rows.join('\n')}\n\n## Data source\n\nGenerated by \`node scripts/top.mjs\` (set \`TOP_N=100\` to regenerate as a Top 100 board). Complete metadata is available in [data/repositories.json](./data/repositories.json).\n`;
}
